-- The society must already exist, and exactly once. These were imported with
-- their flat counts and portal accounts, so a missing one is a mistake to
-- stop on rather than paper over by inserting a second row — and a DUPLICATE
-- one is worse, because every statement below matches by name and would
-- quietly write to both.
DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM societies WHERE name = 'Ace City';
  IF n = 0 THEN RAISE EXCEPTION 'no society named %', 'Ace City'; END IF;
  IF n > 1 THEN RAISE EXCEPTION '% societies named % — resolve the duplicate first', n, 'Ace City'; END IF;
END $$;

UPDATE societies
   SET status = 'active',
       location = 'GH-01, Sector 1, Greater Noida West, Gautam Buddha Nagar, UP 201306',
       -- dedupe_key is derived from name|location and carries the unique
       -- index; it has to move with the address or it describes the old one.
       dedupe_key = btrim(regexp_replace(lower(name), '[^a-z0-9]+', ' ', 'g'))
                    || '|' || btrim(regexp_replace(lower('GH-01, Sector 1, Greater Noida West, Gautam Buddha Nagar, UP 201306'), '[^a-z0-9]+', ' ', 'g'))
 WHERE name = 'Ace City';

INSERT INTO engagements (id, society_id, service_line, status, created_at)
SELECT 'bf-ace-city-eng', s.id, 'lighting', 'active', now() FROM societies s WHERE s.name = 'Ace City' ON CONFLICT DO NOTHING;

