DELETE FROM circuits    WHERE id LIKE 'bf-aditya-mega-city-ckt-%';
DELETE FROM site_surveys WHERE id = 'bf-aditya-mega-city-survey';
DELETE FROM pipelines   WHERE id = 'bf-aditya-mega-city-pipe';
DELETE FROM engagements WHERE id = 'bf-aditya-mega-city-eng';*/

-- The society must already exist, and exactly once. These were imported with
-- their flat counts and portal accounts, so a missing one is a mistake to
-- stop on rather than paper over by inserting a second row — and a DUPLICATE
-- one is worse, because every statement below matches by name and would
-- quietly write to both.
DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM societies WHERE name = 'Aditya Mega City';
  IF n = 0 THEN RAISE EXCEPTION 'no society named %', 'Aditya Mega City'; END IF;
  IF n > 1 THEN RAISE EXCEPTION '% societies named % — resolve the duplicate first', n, 'Aditya Mega City'; END IF;
END $$;

UPDATE societies
   SET status = 'active',
       location = 'Plot No 3, Vaibhav Khand, Indirapuram, Ghaziabad 201014, Uttar Pradesh',
       -- dedupe_key is derived from name|location and carries the unique
       -- index; it has to move with the address or it describes the old one.
       dedupe_key = btrim(regexp_replace(lower(name), '[^a-z0-9]+', ' ', 'g'))
                    || '|' || btrim(regexp_replace(lower('Plot No 3, Vaibhav Khand, Indirapuram, Ghaziabad 201014, Uttar Pradesh'), '[^a-z0-9]+', ' ', 'g'))
 WHERE name = 'Aditya Mega City';

INSERT INTO engagements (id, society_id, service_line, status, created_at)
SELECT 'bf-aditya-mega-city-eng', s.id, 'lighting', 'active', now() FROM societies s WHERE s.name = 'Aditya Mega City' ON CONFLICT DO NOTHING;

