-- The society must already exist, and exactly once. These were imported with
-- their flat counts and portal accounts, so a missing one is a mistake to
-- stop on rather than paper over by inserting a second row — and a DUPLICATE
-- one is worse, because every statement below matches by name and would
-- quietly write to both.
DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM societies WHERE name = 'Aditya Urban Casa';
  IF n = 0 THEN RAISE EXCEPTION 'no society named %', 'Aditya Urban Casa'; END IF;
  IF n > 1 THEN RAISE EXCEPTION '% societies named % — resolve the duplicate first', n, 'Aditya Urban Casa'; END IF;
END $$;

UPDATE societies SET status = 'active' WHERE name = 'Aditya Urban Casa';   -- address left as stored

INSERT INTO engagements (id, society_id, service_line, status, created_at)
SELECT 'bf-aditya-urban-casa-eng', s.id, 'lighting', 'active', now() FROM societies s WHERE s.name = 'Aditya Urban Casa' ON CONFLICT DO NOTHING;

