-- The demo report. Not needed for billing, but without it the deal map sits
-- at "Demo savings report · In progress" while every later step reads done.
INSERT INTO demo_reports (id, pipeline_id, version, status,
                          pre_install_baseline_total, post_install_average_total, measured_savings_pct,
                          society_light_count, metered_light_count, extrapolation_factor,
                          projected_savings_kwh_per_day, circuit_snapshot, generated_at, shared_at, shared_by_id)
SELECT 'bf-aditya-urban-casa-demo-report', 'bf-aditya-urban-casa-pipe', 1, 'shared',
       c.pre_install_baseline, c.pre_install_baseline * (1 - c.benchmark_savings_pct / 100),
       c.benchmark_savings_pct, c.represented_light_count, c.metered_light_count,
       c.represented_light_count::double precision / c.metered_light_count,
       (c.pre_install_baseline * c.benchmark_savings_pct / 100)
         * (c.represented_light_count::double precision / c.metered_light_count),
       '[{"circuitId": "bf-aditya-urban-casa-ckt-1", "lightType": "basement", "location": "Basement", "meteredLightCount": 122, "representedLightCount": 736, "extrapolationFactor": 6.032787, "preInstallBaseline": 59.92, "postInstallAverage": 26.38, "savedKwhPerDay": 33.54, "benchmarkSavingsPct": 66.72, "projectedSavedKwhPerDay": 241.1825, "preInstallReadings": [], "postInstallReadings": []}, {"circuitId": "bf-aditya-urban-casa-ckt-2", "lightType": "lift-lobby", "location": "Lift Lobby", "meteredLightCount": 16, "representedLightCount": 1153, "extrapolationFactor": 72.0625, "preInstallBaseline": 1.81, "postInstallAverage": 0.4, "savedKwhPerDay": 1.41, "benchmarkSavingsPct": 78.0, "projectedSavedKwhPerDay": 101.7378, "preInstallReadings": [], "postInstallReadings": []}]'::jsonb, now(), '2026-01-04'::date, a.id
FROM circuits c, admin_users a
-- shared_by_id is an ADMIN, not a profile: FirsThing shares the report WITH
-- the society, so the sharer is internal. The mirror of offers, where
-- responded_by_id IS a profile because accepting is the society's act.
WHERE c.id = 'bf-aditya-urban-casa-ckt-1' AND a.id = 'sys-data-import' ON CONFLICT DO NOTHING;

INSERT INTO offers (id, pipeline_id, version, status, benchmark_source, circuit_terms,
                    tolerance_pct, revenue_share_pct, unit_electricity_rate, term_months,
                    projected_monthly_fee, issued_at, issued_by_id, responded_at, responded_by_id, created_at)
SELECT 'bf-aditya-urban-casa-offer', 'bf-aditya-urban-casa-pipe', 1, 'accepted', 'negotiated_fixed', '[{"circuitId": "bf-aditya-urban-casa-ckt-1", "lightType": "basement", "location": "Basement", "meteredLightCount": 122, "representedLightCount": 736, "benchmarkSavingsPct": 66.72, "preInstallBaseline": 59.92, "projectedSavedKwhPerDay": 39.9786}]'::jsonb,
       5, 54.00, 7.00, 36,
       23299, '2026-01-04'::date, a.id,
       '2026-01-04'::date, p.id, now()
FROM admin_users a
LEFT JOIN societies soc ON soc.name = 'Aditya Urban Casa'
LEFT JOIN profiles p ON p.society_id = soc.id AND p.portal_authority = 'office_bearer' AND p.is_active
WHERE a.id = 'sys-data-import' ON CONFLICT DO NOTHING;

INSERT INTO agreements (id, pipeline_id, offer_id, prepared_at, prepared_by_id,
                        printed_at, notarized_at, signed_at,
                        executed_s3_key, executed_file_name, uploaded_at, uploaded_by_id)
SELECT 'bf-aditya-urban-casa-agreement', 'bf-aditya-urban-casa-pipe', 'bf-aditya-urban-casa-offer', '2026-01-04'::date, a.id,
       -- Printed and notarised are the same day, and it is the e-stamp
       -- certificate date on page 1 (the user, 2026-08-27). It can fall after
       -- the front-page date, which is a backdated effective date rather than
       -- a mistake.
       '2026-01-04'::date, '2026-01-04'::date,
       '2026-01-04'::date,
       'Documents/Aditya_Urban_Casa/2026-01/Agreements/Aditya_Urban_Casa_Agreement_2026-01-04.pdf',
       'Aditya_Urban_Casa_Agreement_2026-01-04.pdf',
       -- The scan reaches us the day after signing.
       ('2026-01-04'::date + 1), a.id
FROM admin_users a WHERE a.id = 'sys-data-import' ON CONFLICT DO NOTHING;

INSERT INTO contracts (id, pipeline_id, society_id, service_line, agreement_id, status,
                       term_start, term_end, activated_at, activated_by_id, created_at)
SELECT 'bf-aditya-urban-casa-contract', 'bf-aditya-urban-casa-pipe', s.id, 'lighting', 'bf-aditya-urban-casa-agreement', 'active',
       '2026-02-07'::date, ('2026-02-07'::date + '36 months'::interval),
       '2026-02-07'::date, a.id, now()
FROM societies s, admin_users a WHERE s.name = 'Aditya Urban Casa' AND a.id = 'sys-data-import' ON CONFLICT DO NOTHING;

INSERT INTO contract_term_versions (id, contract_id, version, effective_from, benchmark_source,
                                    tolerance_pct, revenue_share_pct, unit_electricity_rate,
                                    circuit_benchmarks, recorded_by_id, recorded_at)
SELECT 'bf-aditya-urban-casa-terms', 'bf-aditya-urban-casa-contract', 1, '2026-02-07'::date, 'negotiated_fixed',
       5, 54.00, 7.00,
       '[{"circuitId": "bf-aditya-urban-casa-ckt-1", "lightType": "basement", "location": "Basement", "meteredLightCount": 122, "representedLightCount": 736, "benchmarkSavingsPct": 66.72, "preInstallBaseline": 59.92, "projectedSavedKwhPerDay": 39.9786}]'::jsonb, a.id, now()
FROM admin_users a WHERE a.id = 'sys-data-import' ON CONFLICT DO NOTHING;



