king area", "dailyReadings": [], "clarifications": [{"id": "clarification-installation-completion-date", "because": "Section 3 specifies that the agreement is valid for 3 years from the date of installation completion, but this date is not defined in the contract.", "options": ["To be established upon completion of installation", "Starts on Effective Date (23 Oct 2025)", "Starts on Signature/Stamp Date (10 Nov 2025)"], "question": "What is the exact date of installation completion from which the 3-year contract term commences?", "sourceText": "This Agreement shall remain valid for three years from the date of installation completion."}], "societySharePct": {"value": 100, "sourceText": "100%"}, "wattagePerLight": {"value": 20, "sourceText": "Wattage 20W"}, "baselineDailyKwh": {"value": null, "sourceText": ""}, "firsthingSharePct": {"value": 36, "sourceText": "~36%"}, "contractTermMonths": {"value": 36, "sourceText": "36 months"}, "theoreticalDailyKwh": {"value": null, "sourceText": ""}, "contractedLightCount": {"value": 2500, "sourceText": "2,500 lights"}, "operatingHoursPerDay": {"value": 24, "sourceText": "operates 24x7"}, "societyNameOnDocument": "Ace City Apartment Owners Association", "monthlyServiceChargeInr": {"value": 54214, "sourceText": "₹ 54,214"}}', NULL, NULL, '2026-08-26T12:56:29.988', NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO document_extractions (id, document_id, status, proposed, confirmed, model_error, extracted_at, confirmed_at, confirmed_by_id) VALUES ('cmta3kbek00029sqsccf5h91d', 'cmta3ixjm00019sqsw1u70j5s', 'confirmed', '{"dates": [{"label": "Report Date", "value": "25 Aug 2025", "sourceText": "Date: 25 Aug 2025"}, {"label": "Recorded Energy Consumption (Pre-Installation) Period Start", "value": "03 Aug 2025", "sourceText": "(03–10 Aug 2025)"}, {"label": "Recorded Energy Consumption (Pre-Installation) Period End", "value": "10 Aug 2025", "sourceText": "(03–10 Aug 2025)"}], "notes": "Only the company share percentage (50%) was explicitly stated in the document text; the society share percentage was not printed and has been left null per Rule 6. The post-installation table dates lack a clear year consistent with the report date of 25 Aug 2025, so their date field is left blank per Rule 3.", "fixtures": [{"count": 96, "label": "Tube lights", "watts": 20, "sourceText": "96 tube lights (20 watts each)", "hoursPerDay": 24, "retrofitted": true}], "notFound": ["societyNameOnDocument", "areaOrCircuit", "societySharePct", "contractTermMonths", "contractedLightCount", "monthlyServiceChargeInr"], "periodEnd": "", "lightCount": {"value": 96, "sourceText": "96 tube lights (20 watts each)"}, "savingsPct": {"value": 66.4, "sourceText": "66.40%"}, "periodStart": "03 Aug 2025", "documentKind": "Energy Consumption Analysis and Recommendation Report", "afterDailyKwh": {"value": 16.36, "sourceText": "16.36 kWh/Day"}, "areaOrCircuit": "", "dailyReadings": [{"kwh": 48.84, "date": "03/08/2025", "window": "Recorded Energy Consumption (Pre-Installation)", "sourceText": "03/Aug: 48.84"}, {"kwh": 48.79, "date": "04/08/2025", "window": "Recorded Energy Consumption (Pre-Installation)", "sourceText": "04/Aug: 48.79"}, {"kwh": 48.35, "date": "05/08/2025", "window": "Recorded Energy Consumption (Pre-Installation)", "sourceText": "05/Aug: 48.35"}, {"kwh": 48.33, "date": "06/08/2025", "window": "Recorde